/** Native viewBox size of each icon in the Figma set (24 unless listed) */
const BOX: Partial<Record<IconName, number>> = { checkmark: 12, sEdit: 16, pdf: 16, contact: 16, word: 16, jpeg: 16, yes: 16, check: 16, fabAdd: 32, roleClientF: 32, roleClient: 32, roleContractor: 32, roleArchitect: 32 };

export type IconName = keyof typeof RAW;

const HTML = Object.fromEntries(Object.entries(RAW).map(([k, v]) => [k, v.replace(/"C"/g, '"currentColor"')])) as Record<IconName, string>;

export function Icon({ name, size, ...p }: { name: IconName; size?: number } & Omit<SVGProps<SVGSVGElement>, 'name'>) {
  const box = BOX[name] ?? 24;
  const s = size ?? box;
  return <svg width={s} height={s} viewBox={`0 0 ${box} ${box}`} fill="none" aria-hidden {...p} className={['shrink-0', p.className].filter(Boolean).join(' ')} dangerouslySetInnerHTML={{ __html: HTML[name] }} />;
}
